<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignment\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\UserRoleAssignmentRef;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Application\Service\Visibility\UserRoleAssignmentVisibilityService;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\Gateway\UserRoleAssignmentQueryRepositoryGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserRoleAssignmentRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserRoleAssignmentVisibilityService $visibility,
        private readonly UserRoleAssignmentQueryRepositoryGateway $reader
    ) {
    }

    public function allowRetrieve(?UserRoleAssignmentRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for User role assignment");
        $span = $this->startSpan("Check allow of retrieve usecase for User role assignment");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignmentRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?UserRoleAssignmentRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for User role assignment");
        $span = $this->startSpan("Check hidden fields usecase for User role assignment");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): UserRoleAssignmentRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for User role assignment");
        $span = $this->startSpan("Run retrieve usecase for User role assignment");
        try {
            $ref = new UserRoleAssignmentRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve User role assignment');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserRoleAssignmentRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
